/**
 * Render the extracted ADT (Qt) guide as a standalone HTML download.
 * The Markdown source is generated by scripts/sync-docs.py.
 */
import { readFile, writeFile } from 'node:fs/promises'
import { createRequire } from 'node:module'

const site = new URL('../docs/site/', import.meta.url)
const require = createRequire(new URL('package.json', site))
const MarkdownIt = require('markdown-it')
const markdown = new MarkdownIt({ html: false })
const sections = []

markdown.renderer.rules.heading_open = (tokens, index, options, environment, renderer) => {
  const title = tokens[index + 1].content
  const anchor = title.toLowerCase().replace(/[^\w\s-]/g, '').trim().replace(/\s+/g, '-')
  tokens[index].attrSet('id', anchor)
  if (tokens[index].tag === 'h2') sections.push({ title, anchor })
  return renderer.renderToken(tokens, index, options)
}

const downloads = new URL('public/downloads/', site)
const guide = await readFile(new URL('adt-qt-guide.md', downloads), 'utf8')
const rendered = markdown.render(guide)
const contents = sections.map(section =>
  `<li><a href="#${section.anchor}">${markdown.utils.escapeHtml(section.title)}</a></li>`
).join('\n')
const body = rendered.replace('</h1>', `</h1>
<nav aria-label="Contents"><h2>Contents</h2><ul>${contents}</ul></nav>`)
const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>ADT (Qt) User Manual</title>
<style>
body{font:16px/1.6 system-ui,sans-serif;max-width:960px;margin:40px auto;padding:0 20px;color:#202020;background:#fff}
h1,h2,h3{line-height:1.3}h2{margin-top:2em}a{color:#176c98}
table{border-collapse:collapse}td,th{border:1px solid #ccc;padding:6px 10px;text-align:left}
code{background:#f1f4f6;padding:2px 4px}pre{overflow:auto;background:#f1f4f6;padding:12px}
nav{background:#f1f4f6;padding:12px 24px;border-radius:8px}
</style>
</head>
<body>
${body}
</body>
</html>
`
await writeFile(new URL('adt-manual.html', downloads), html)
console.log(`Rendered the standalone manual with ${sections.length} guide topics.`)
